def render_signature(sig: inspect.Signature, max_line_len: Optional[int]=
    None, prefix: str='') ->str:
    params = []
    for param in sig.parameters.values():
        rendered = render_parameter(param)
        params.append(rendered)

    return_annotation = ''
    if sig.return_annotation is not inspect.Signature.empty:
        return_annotation = ' -> ' + render_annotation(sig.return_annotation)

